commit a74a2627f55efa7d80da11a1946cfa37c942bb9f
Author: anthnel <anthoni.devops@proton.me>
Date:   Tue Nov 10 12:04:32 2026 +0100

    refactor: port the theme to color.Color and validate theme hex values (DEVDESK-201)

    Palette variables, ContrastRatio/ColorDistance and IconColor/TokenColor are
    color.Color; components are read through RGBA() after a color.RGBA type check.
    theme.Hex formats a colour. LoadTheme refuses a non-empty colour that is not
    #rgb/#rrggbb, naming the key and value. StyleTextInput uses textinput v2
    Styles(). The colorprofile test helper is a no-op (H2).

    also: indicator and cmdsuggest types and tests.
    Entire-Checkpoint: 15810f475b1f

diff --git a/docs/architecture/configuration.md b/docs/architecture/configuration.md
index 58afd28..3bb9618 100644
--- a/docs/architecture/configuration.md
+++ b/docs/architecture/configuration.md
@@ -12,6 +12,12 @@ Config loaded from `~/.devdesk/config.yaml` with schema defined in `internal/con
   the default. An absent key stays absent (it is not written back at load)
   because the default may change with A-06; an explicit value keeps its meaning
   when it does.
+  `app.theme` names a JSON file under `~/.devdesk/themes/`. `theme.LoadTheme` refuses the
+  whole file when a non-empty colour is not `#rgb` or `#rrggbb` (error names the key and the
+  value, e.g. `color_ok: "#ggg" is not #rgb or #rrggbb`); an empty or absent optional colour
+  falls back to the semantic palette. `main.go` and `App.applyThemeNow` log the error and keep
+  the current palette (no footer message). Palette variables are `color.Color`; `theme.Hex`
+  formats one as `#rrggbb` (`none` for anything that is not a `color.RGBA`).
 - `Status` - Monitoring settings (refresh interval, components)
 - `Forge` - the platform this context targets: `type`, URL and clone settings
 - `Registry` - OCI registry configuration (see Registry model below)
diff --git a/internal/app/theme_invalid_test.go b/internal/app/theme_invalid_test.go
new file mode 100644
index 0000000..91f56bd
--- /dev/null
+++ b/internal/app/theme_invalid_test.go
@@ -0,0 +1,56 @@
+package app
+
+import (
+	"os"
+	"path/filepath"
+	"testing"
+
+	"github.com/anthnel/devdesk/internal/ui/components"
+	"github.com/anthnel/devdesk/internal/ui/configuration"
+	"github.com/anthnel/devdesk/internal/ui/testutil"
+	"github.com/anthnel/devdesk/internal/ui/theme"
+)
+
+// DEVDESK-201, H3: LoadTheme refuses a theme with an invalid hex, and the
+// router keeps the current palette. No footer message is added (a follow-up if
+// the user asks for one): the failure goes to the log only.
+func TestASavedThemeWithAnInvalidHexKeepsTheCurrentPaletteAndPostsNoFooter(t *testing.T) {
+	a := router(t, &fakeView{})
+	t.Cleanup(func() {
+		theme.ApplyTheme(theme.DefaultTheme())
+		theme.CurrentThemeName = "default"
+	})
+	theme.ApplyTheme(theme.DefaultTheme())
+	theme.CurrentThemeName = "default"
+
+	dir, err := theme.ThemeDir()
+	if err != nil {
+		t.Fatal(err)
+	}
+	if err := os.MkdirAll(dir, 0o755); err != nil {
+		t.Fatal(err)
+	}
+	bad := `{"name":"broken","color_ok":"#ggg","color_error":"#ff0000","color_warn":"#ff8800",` +
+		`"color_primary":"#0000ff","color_secondary":"#8888ff","color_border":"#cccccc","color_text":"#000000",` +
+		`"color_dim":"#888888","color_highlight":"#ffff00","color_white":"#ffffff","color_black":"#000000"}`
+	if err := os.WriteFile(filepath.Join(dir, "broken.json"), []byte(bad), 0o644); err != nil {
+		t.Fatal(err)
+	}
+
+	before := theme.Hex(theme.ColorPrimary)
+	cfg := testConfig()
+	cfg.App.Theme = "broken"
+	_, cmd := a.Update(configuration.ConfigSavedMsg{Config: cfg, ThemeChanged: true})
+
+	if got := theme.Hex(theme.ColorPrimary); got != before {
+		t.Errorf("ColorPrimary = %s after a refused theme, want %s kept", got, before)
+	}
+	if theme.CurrentThemeName != "default" {
+		t.Errorf("CurrentThemeName = %q, want %q kept", theme.CurrentThemeName, "default")
+	}
+	for _, m := range testutil.Msgs(cmd) {
+		if p, ok := m.(components.PostFooterMsg); ok {
+			t.Errorf("a refused theme posted a footer message: %+v", p)
+		}
+	}
+}
