+		"empty":      lipgloss.Color(""),
+		"ANSI index": lipgloss.Color("5"),
+		"nil":        nil,
+	} {
+		t.Run(name, func(t *testing.T) {
+			if _, err := ContrastRatio(c, white); err == nil {
