+		}
+		if got := state.Text.GetBackground(); got != ColorBackground {
+			t.Errorf("%s text background = %s, want the app background %s (Rule 115)", name, Hex(got), Hex(ColorBackground))
+		}
+		if got := state.Placeholder.GetForeground(); got != ColorDim {
