// LoadTheme loads a theme from a JSON file.
// If name is empty, "dark" or "default", returns the built-in default theme
func LoadTheme(name string) (*Theme, error) {
	if name == "" || name == "dark" || name == "default" {
		return DefaultTheme(), nil
	}

	dir, err := ThemeDir()
	if err != nil {
		return nil, fmt.Errorf("failed to get theme directory: %w", err)
	}

	path := filepath.Join(dir, name+".json")
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("failed to read theme '%s': %w", name, err)
	}

	var t Theme
	if err := json.Unmarshal(data, &t); err != nil {
		return nil, fmt.Errorf("failed to parse theme '%s': %w", name, err)
	}

	if err := validateTheme(&t); err != nil {
		return nil, fmt.Errorf("invalid theme '%s': %w", name, err)
	}

	// Ensure the name is set
	if t.Name == "" {
		t.Name = name
	}

	return &t, nil
}

// ListThemes returns the list of available themes.
// Always includes "default" (built-in theme) + the JSON files in the themes directory
func ListThemes() ([]string, error) {
	themes := []string{"default"}

	dir, err := ThemeDir()
	if err != nil {
		log.Printf("Config loaded from context: %s", getCurrentContextName())
		log.Printf("Log file: %s", cfg.App.LogFile)
		log.Printf("DEBUG mode: %v", len(os.Getenv("DEBUG")) > 0)
	}

	// Load and apply the saved theme
	if cfg.App.Theme != "" && cfg.App.Theme != "dark" {
		t, err := theme.LoadTheme(cfg.App.Theme)
		if err != nil {
			log.Printf("Warning: Could not load theme '%s': %v, using default", cfg.App.Theme, err)
		} else {
			theme.ApplyTheme(t)
			theme.CurrentThemeName = cfg.App.Theme
			log.Printf("Theme loaded: %s", cfg.App.Theme)
		}
	}

	theme.SetGaugeGlyph(cfg.App.GaugeGlyph)

	// Create the application with the router
	m := app.New(cfg)

	motionCmd := a.applyMotion(msg.Config)

	return a, tea.Batch(a.requestResize(), a.syncProxyPortCmd(), a.redetectIfToolsMoved(msg.EngineChanged), motionCmd)
}

// applyThemeNow switches the palette in place.
//
// It does not save: the configuration view already did, and writing twice would
// make the view's own config object and the file disagree about who is
// authoritative. That double write is what the `:theme` command did — it is
// gone, and this replaced it.
func (a *App) applyThemeNow(name string) {
	t, err := theme.LoadTheme(name)
	if err != nil {
		log.Printf("ERROR [app] load theme %q: %v", name, err)
		return
	}
	theme.ApplyTheme(t)
	theme.CurrentThemeName = name
}

// resolveSecretBackend picks up the new app.secret_backend for this context.
//
// Nothing is migrated between backends. §3.9 removed the option that wrote a
// token to two stores at once, and copying one here would rebuild exactly that.
// The configuration view has already told the user their secrets will need
// re-entering, which is why this can be a plain re-resolve.
func (a *App) resolveSecretBackend() {
	selection := credentials.Select(a.currentContext, a.config.App.SecretBackend)
	a.sharedState.Secrets = selection
	a.sharedState.SecretNotices = nil

	// The GitLab session was authenticated against the previous store, so it no
	// longer has a token behind it. Saying so beats a client that fails on its
	// next call.
	a.clearAuthenticated()
